<span class="line"><span style="color:#F97583;">import</span><span style="color:#E1E4E8;"> { injectAccordionItemContext, injectAccordionRootContext } </span><span style="color:#F97583;">from</span><span style="color:#9ECBFF;"> &#39;reka-ui&#39;</span></span>
